<?php if (!defined('ABSPATH')) { exit; } ?>
<div class="wrap ses-admin"><h1>Logs</h1><div class="ses-card"><table class="widefat striped"><thead><tr><th>Data</th><th>Post</th><th>Ação</th><th>Status</th><th>Mensagem</th></tr></thead><tbody><?php foreach ((array) ($logs ?? array()) as $log) : ?><tr><td><?php echo esc_html($log->created_at ?? ''); ?></td><td><?php echo esc_html($log->post_id ?? ''); ?></td><td><?php echo esc_html($log->action ?? ''); ?></td><td><?php echo esc_html($log->status ?? ''); ?></td><td><?php echo esc_html($log->message ?? ''); ?></td></tr><?php endforeach; ?></tbody></table></div></div>
